import { useState, useEffect } from 'react';
import client from '../../api/client';

const formatCOP = (v) =>
  new Intl.NumberFormat('es-CO', { style:'currency', currency:'COP', minimumFractionDigits:0 }).format(v||0);

const emptyItem = { productoId: '', nombreProducto: '', cantidad: 1, costoUnitario: '' };

export default function Compras() {
  const [compras, setCompras]       = useState([]);
  const [proveedores, setProveedores] = useState([]);
  const [productos, setProductos]   = useState([]);
  const [showForm, setShowForm]     = useState(false);
  const [loading, setLoading]       = useState(false);
  const [detalle, setDetalle]       = useState(null);
  const [form, setForm] = useState({ proveedorId:'', metodoPago:'Efectivo', observaciones:'', items:[{ ...emptyItem }] });

  useEffect(() => { cargar(); }, []);

  const cargar = async () => {
    const [cRes, pRes, prRes] = await Promise.all([
      client.get('/api/compras'),
      client.get('/api/productos'),
      client.get('/api/proveedores'),
    ]);
    setCompras(cRes.data);
    setProductos(pRes.data);
    setProveedores(prRes.data);
  };

  const agregarItem = () => setForm(f => ({ ...f, items: [...f.items, { ...emptyItem }] }));
  const quitarItem  = (i) => setForm(f => ({ ...f, items: f.items.filter((_, idx) => idx !== i) }));

  const cambiarItem = (i, key, val) => setForm(f => ({
    ...f,
    items: f.items.map((item, idx) => idx === i ? { ...item, [key]: val } : item),
  }));

  const total = form.items.reduce((s, i) => s + (parseFloat(i.costoUnitario)||0) * (parseInt(i.cantidad)||0), 0);

  const guardar = async (e) => {
    e.preventDefault(); setLoading(true);
    try {
      await client.post('/api/compras', {
        proveedorId: form.proveedorId || null,
        metodoPago: form.metodoPago,
        observaciones: form.observaciones,
        items: form.items.map(i => ({
          productoId: i.productoId || null,
          nombreProducto: i.nombreProducto || null,
          cantidad: parseInt(i.cantidad),
          costoUnitario: parseFloat(i.costoUnitario),
        })),
      });
      setShowForm(false);
      setForm({ proveedorId:'', metodoPago:'Efectivo', observaciones:'', items:[{ ...emptyItem }] });
      cargar();
    } catch (err) { alert(err.response?.data?.error || 'Error'); }
    finally { setLoading(false); }
  };

  return (
    <div>
      <div className="page-header">
        <h1 className="page-title">🚚 Compras</h1>
        <button className="btn btn-primary" onClick={() => setShowForm(true)}>+ Nueva compra</button>
      </div>

      <div className="card table-wrap">
        <table>
          <thead><tr><th>#</th><th>Fecha</th><th>Proveedor</th><th>Total</th><th>Método</th><th>Acciones</th></tr></thead>
          <tbody>
            {compras.map(c => (
              <tr key={c.id}>
                <td><strong>#{c.id}</strong></td>
                <td>{new Date(c.createdAt).toLocaleDateString('es-CO')}</td>
                <td>{c.Proveedor?.nombre || '—'}</td>
                <td><strong>{formatCOP(c.total)}</strong></td>
                <td>{c.metodoPago}</td>
                <td>
                  <button className="btn btn-secondary" style={{ padding:'4px 10px', fontSize:'.78rem' }}
                    onClick={() => setDetalle(detalle?.id === c.id ? null : c)}>
                    {detalle?.id === c.id ? 'Ocultar' : 'Ver'}
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {detalle && (
        <div className="card" style={{ marginTop:16 }}>
          <h3 style={{ marginBottom:12 }}>Detalle compra #{detalle.id}</h3>
          <table>
            <thead><tr><th>Producto</th><th>Cantidad</th><th>Costo unit.</th><th>Subtotal</th></tr></thead>
            <tbody>
              {detalle.CompraItems?.map(i => (
                <tr key={i.id}>
                  <td>{i.Producto?.nombre || i.nombreProducto || '—'}</td>
                  <td>{i.cantidad}</td>
                  <td>{formatCOP(i.costoUnitario)}</td>
                  <td>{formatCOP(i.subtotal)}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      {showForm && (
        <div className="modal-overlay">
          <div className="modal-box" style={{ maxWidth:640 }}>
            <h3>Nueva compra</h3>
            <form onSubmit={guardar} style={{ marginTop:16, display:'flex', flexDirection:'column', gap:12 }}>
              <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr', gap:12 }}>
                <div className="field"><label>Proveedor</label>
                  <select value={form.proveedorId} onChange={e => setForm({ ...form, proveedorId: e.target.value })}>
                    <option value="">— Sin proveedor —</option>
                    {proveedores.map(p => <option key={p.id} value={p.id}>{p.nombre}</option>)}
                  </select>
                </div>
                <div className="field"><label>Método de pago *</label>
                  <select value={form.metodoPago} onChange={e => setForm({ ...form, metodoPago: e.target.value })}>
                    <option>Efectivo</option>
                    <option>Nequi</option>
                    <option>Consignacion</option>
                  </select>
                </div>
              </div>

              <div className="field"><label>Observaciones</label>
                <textarea rows={2} value={form.observaciones} onChange={e => setForm({ ...form, observaciones: e.target.value })} />
              </div>

              <div>
                <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center', marginBottom:8 }}>
                  <label style={{ fontWeight:700 }}>Productos</label>
                  <button type="button" className="btn btn-secondary" style={{ padding:'4px 10px', fontSize:'.78rem' }} onClick={agregarItem}>+ Agregar línea</button>
                </div>
                {form.items.map((item, i) => (
                  <div key={i} style={{ display:'grid', gridTemplateColumns:'2fr 1fr 1fr auto', gap:8, marginBottom:8 }}>
                    <select value={item.productoId}
                      onChange={e => {
                        const p = productos.find(p => p.id === parseInt(e.target.value));
                        cambiarItem(i, 'productoId', e.target.value);
                        if (p) cambiarItem(i, 'nombreProducto', p.nombre);
                      }}>
                      <option value="">— Seleccionar —</option>
                      {productos.map(p => <option key={p.id} value={p.id}>{p.nombre}</option>)}
                    </select>
                    <input type="number" min="1" placeholder="Cant." value={item.cantidad}
                      onChange={e => cambiarItem(i, 'cantidad', e.target.value)} />
                    <input type="number" min="0" placeholder="Costo" value={item.costoUnitario}
                      onChange={e => cambiarItem(i, 'costoUnitario', e.target.value)} />
                    {form.items.length > 1 && (
                      <button type="button" className="btn btn-danger" style={{ padding:'4px 8px' }} onClick={() => quitarItem(i)}>🗑</button>
                    )}
                  </div>
                ))}
                <p style={{ textAlign:'right', fontWeight:700, color:'#1a1a2e' }}>Total: {formatCOP(total)}</p>
              </div>

              <div style={{ display:'flex', gap:10, justifyContent:'flex-end', marginTop:8 }}>
                <button type="button" className="btn btn-secondary" onClick={() => setShowForm(false)}>Cancelar</button>
                <button type="submit" className="btn btn-primary" disabled={loading}>{loading ? 'Guardando...' : 'Registrar compra'}</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}
